SELECT mode,algorithm_version,experiment_group,count() AS learned_materials,avgOrNull(attempts_to_learned) AS attempts,avgOrNull(seconds_to_learned) AS observed_seconds FROM knowledge_analytics.learned_materials WHERE $__timeFilter(learned_at) AND (${mode:sqlstring}='__all' OR mode=${mode:sqlstring}) AND (${algorithm:sqlstring}='__all' OR algorithm_version=${algorithm:sqlstring}) AND (${experiment:sqlstring}='__all' OR experiment_group=${experiment:sqlstring}) GROUP BY mode,algorithm_version,experiment_group
